public class Main {
    static int countParts(String text, String part) {
        if (part.isEmpty()) {
            return 0;
        }
        int count = 0;
        int from = 0;
        while (true) {
            int found = text.indexOf(part, from);
            if (found == -1) {
                break;
            }
            count = count + 1;
            from = found + part.length();
        }
        return count;
    }
    public static void main(String[] args) {
        System.out.println(countParts("aaaa", "aa"));
    }
}

